package ai.taskforge.domain;
import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="document_chunks",indexes=@Index(name="idx_chunk_document",columnList="document_id")) public class DocumentChunk { @Id @GeneratedValue private UUID id; @ManyToOne(optional=false) @JoinColumn(name="document_id") private Document document; @Column(nullable=false) private int chunkIndex; @Column(length=3000,nullable=false) private String content; @Column(length=4000,nullable=false) private String embedding; protected DocumentChunk(){} public DocumentChunk(Document d,int i,String c,String e){document=d;chunkIndex=i;content=c;embedding=e;} public UUID getId(){return id;} public Document getDocument(){return document;} public int getChunkIndex(){return chunkIndex;} public String getContent(){return content;} public String getEmbedding(){return embedding;} }
